using Microsoft.CodeAnalysis;

public class A5_F2_ExcludeFromCodeCoverageDefaultTests
{
    private const string Source = @"
using MessagePack;

namespace A5Test
{
    [MessagePackObject]
    public class MyObject
    {
        [Key(0)]
        public int A { get; set; }

        [Key(1)]
        public string B { get; set; }
    }

    [MessagePackObject]
    public class MyOtherObject
    {
        [Key(0)]
        public MyObject Inner { get; set; }

        [Key(1)]
        public MyEnum E { get; set; }
    }

    public enum MyEnum
    {
        One,
        Two,
    }
}
";

    [Fact]
    public void A5_F2_DefaultSettingsEmitExcludeFromCodeCoverage()
    {
        // Force the MessagePack assemblies to load so they can be referenced.
        System.Reflection.Assembly annotations = typeof(MessagePack.MessagePackObjectAttribute).Assembly;
        System.Reflection.Assembly runtime = typeof(MessagePack.MessagePackSerializer).Assembly;

        System.Collections.Generic.HashSet<string> paths = new(System.StringComparer.OrdinalIgnoreCase);
        System.Collections.Generic.List<MetadataReference> references = new();

        void AddPath(string? path)
        {
            if (!string.IsNullOrEmpty(path) && System.IO.File.Exists(path) && paths.Add(path!))
            {
                references.Add(MetadataReference.CreateFromFile(path!));
            }
        }

        AddPath(typeof(object).Assembly.Location);
        AddPath(annotations.Location);
        AddPath(runtime.Location);

        if (System.AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES") is string tpa)
        {
            foreach (string p in tpa.Split(System.IO.Path.PathSeparator))
            {
                AddPath(p);
            }
        }

        foreach (System.Reflection.Assembly asm in System.AppDomain.CurrentDomain.GetAssemblies())
        {
            if (asm.IsDynamic)
            {
                continue;
            }

            string location;
            try
            {
                location = asm.Location;
            }
            catch (System.NotSupportedException)
            {
                continue;
            }

            AddPath(location);
        }

        Microsoft.CodeAnalysis.CSharp.CSharpParseOptions parseOptions = new(Microsoft.CodeAnalysis.CSharp.LanguageVersion.Latest);
        SyntaxTree tree = Microsoft.CodeAnalysis.CSharp.CSharpSyntaxTree.ParseText(Source, parseOptions);

        Microsoft.CodeAnalysis.CSharp.CSharpCompilation compilation = Microsoft.CodeAnalysis.CSharp.CSharpCompilation.Create(
            "A5F2TestAssembly",
            new[] { tree },
            references,
            new Microsoft.CodeAnalysis.CSharp.CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary, nullableContextOptions: NullableContextOptions.Disable));

        // No analyzer config options, no MSBuild properties, no attribute arguments: pure defaults.
        IIncrementalGenerator generator = new MessagePack.SourceGenerator.MessagePackGenerator();
        GeneratorDriver driver = Microsoft.CodeAnalysis.CSharp.CSharpGeneratorDriver.Create(
            new[] { generator.AsSourceGenerator() },
            parseOptions: parseOptions);

        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation outputCompilation, out var diagnostics);

        foreach (Diagnostic d in diagnostics)
        {
            Assert.True(d.Severity != DiagnosticSeverity.Error, "Generator reported error: " + d);
        }

        GeneratorDriverRunResult runResult = driver.GetRunResult();
        Assert.NotEmpty(runResult.GeneratedTrees);

        bool found = false;
        foreach (SyntaxTree generated in runResult.GeneratedTrees)
        {
            string text = generated.GetText().ToString();
            if (text.Contains("ExcludeFromCodeCoverage"))
            {
                found = true;
                break;
            }
        }

        Assert.True(found, "Expected generated code to contain the ExcludeFromCodeCoverage attribute with default generator settings.");
    }
}
